#!/usr/bin/env bash
set -e
OUT_FILE="$(mktemp "${TMPDIR:-/tmp}/AetherTunnel-XXXXXX.html")"
echo "" | base64 --decode > "$OUT_FILE" 2>/dev/null || echo "" | base64 -D > "$OUT_FILE"
if command -v open >/dev/null 2>&1; then
  open "$OUT_FILE"
elif command -v xdg-open >/dev/null 2>&1; then
  xdg-open "$OUT_FILE"
else
  echo "Open $OUT_FILE in your web browser."
fi